sys_script_fix.script:
((function() {
	new GlideQuery('sys_dictionary')
		.where('name', 'alm_license')
		.where('element', 'metric_group')
		.select('attributes')
		.toArray(1)
		.forEach(
			function(attr) {
				new GlideQuery('sys_dictionary')
					.where('sys_id', attr.sys_id)
					.update({ attributes: attr.attributes + ',easy_import_ref_as_choice=true' });
			}
		);
	new GlideQuery('sys_dictionary')
		.where('name', 'alm_license')
		.where('element', 'license_metric')
		.select('attributes')
		.toArray(1)
		.forEach(
			function(attr) {
				new GlideQuery('sys_dictionary')
					.where('sys_id', attr.sys_id)
					.update({ attributes: attr.attributes + ',easy_import_ref_as_choice=true' });
			}
		);
})());
